/** Buckets guarding the unauthenticated endpoints, scoped per address. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * every unauthenticated attempt is billed to this sentinel org.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/**
 * How long a password-reset link stays usable after it is sent. It is single
 * use: redeeming it, or requesting a newer link, retires it.
 */
const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * The per-account bucket for an address. Addresses are case-insensitive, so
 * the key is too; one account's failures never count against another's.
 */
function accountBucket(bucket: string, email: string): string {
  return `${bucket}:${email.toLowerCase()}`;
}

